import operator


def _prime_factorization(n):
    """Return the prime factorization of a positive integer as {prime: exponent}."""
    factors = {}
    divisor = 2
    while divisor * divisor <= n:
        while not n % divisor:
            factors[divisor] = factors.get(divisor, 0) + 1
            n //= divisor
        divisor += 1
    if n > 1:
        factors[n] = factors.get(n, 0) + 1
    return factors


def _factorial_prime_exponent(n, prime):
    """Return the exponent of ``prime`` in ``n!`` (Legendre's formula)."""
    exponent = 0
    while n:
        n //= prime
        exponent += n
    return exponent


def first_Factorial_Divisible_Number(x):
    """Write a python function to find the first natural number whose factorial is divisible by x."""
    try:
        x = operator.index(x)
    except TypeError:
        raise TypeError("x must be an integer") from None
    if not x:
        raise ValueError("x must be non-zero: divisibility by zero is undefined")
    x = abs(x)

    answer = 1
    for prime, exponent in _prime_factorization(x).items():
        # (prime * exponent)! contains at least ``exponent`` factors of
        # ``prime``, so the minimal n for this prime power lies in [1, prime * exponent].
        low, high = 1, prime * exponent
        while low < high:
            mid = (low + high) // 2
            if _factorial_prime_exponent(mid, prime) >= exponent:
                high = mid
            else:
                low = mid + 1
        answer = max(answer, low)
    return answer
